{"query":"-- Compute ln(P(X=0)) = ln(gamma(1897)) - ln(gamma(1897-65)) - (ln(gamma(2198)) - ln(gamma(2198-65)))
WITH vars AS (
  SELECT 
    lgamma(1897.0) - lgamma(1832.0) - (lgamma(2198.0) - lgamma(2133.0)) AS log_p
)
SELECT log_p, exp(log_p) AS p_val FROM vars"}
